#include "../src/game/level1_cutscenes.hpp"
#include "../src/assets/asset_store.hpp"
#include <stdexcept>
void check(bool b){if(!b)throw std::runtime_error("cutscene test");}
int main(int argc,char**argv){shin::Level1Intro intro;auto f=intro.update(100,false);check(f.draws[1].resource=="enoop01.app");intro.update(1100,false);check(intro.phase()==0);intro.update(1101,false);check(intro.phase()==1);f=intro.update(1102,true);check(f.action==shin::CutsceneFrame::resume_level);check(intro.update(1200,false).draws.empty());shin::Level1Intro complete;unsigned now=0;bool done=false;for(int i=0;i<5000&&!done;++i){f=complete.update(now,false);now+=16;done=f.action==shin::CutsceneFrame::resume_level;}check(done);shin::GlobalEnding ending(0);f=ending.update(0,false);check(f.cd_track==11&&f.sounds.size()==1);f=ending.update(1,true);check(f.action==shin::CutsceneFrame::credits);shin::EndingCredits credits;for(int i=0;i<4000;++i)check(credits.update().action==shin::CutsceneFrame::none);check(credits.update().action==shin::CutsceneFrame::main_menu);if(argc>1){shin::AssetStore a(argv[1]);for(auto n:shin::intro_assets)a.image(n);for(auto n:shin::ending_assets)a.image(n);for(auto n:{"evframe.app","airplane.app","fuck-1.app","fuck-2.app","fuck-3.app"})a.image(n);}}
